"""Generate deterministic initialized gamma ROM RTL; no runtime .mem paths."""
from pathlib import Path
import math

ROOT=Path(__file__).resolve().parents[1]
EXPONENTS=(0.50,0.65,0.80,1.0,1.25,1.55,1.90,1.0)

def generate():
    lines=["`timescale 1ns/1ps",
           "// Generated by tests/generate_adaptive_gamma_lut.py; do not hand-edit.",
           "// result=round(255*(value/255)^exponent); curve 7 is safe identity.",
           "// 2048x8 synchronous initialized ROM, one result per clock.",
           "module adaptive_gamma_lut(input clk, input [2:0] curve, input [7:0] value, output reg [7:0] result);",
           "    reg [7:0] rom[0:2047];", "    initial begin"]
    for c,e in enumerate(EXPONENTS):
        lines.append(f"        // curve {c}, exponent {e:.2f}")
        for v in range(256):
            result=math.floor(255*(v/255)**e+0.5)
            lines.append(f"        rom[{c*256+v}]=8'd{result};")
    lines += ["    end", "    always @(posedge clk) result<=rom[{curve,value}];", "endmodule", ""]
    return '\n'.join(lines)

if __name__=='__main__':
    (ROOT/'src/video/preprocess/adaptive_gamma_lut.v').write_text(generate(),encoding='ascii')
